document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll("section .container-fluid");if(0===e.length)return;e.forEach(e=>e.classList.add("reveal"));const t=new IntersectionObserver((e,t)=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("visible"),t.unobserve(e.target))})},{root:null,threshold:.15});e.forEach(e=>t.observe(e))});